if (partyLevel <= 5) {
  availableCreatures.push(...creatureDatabase.lowLevel, ...creatureDatabase.midLevel);
} else if (partyLevel <= 10) {
  availableCreatures.push(...creatureDatabase.midLevel);
} else {
  availableCreatures.push(...creatureDatabase.midLevel, ...creatureDatabase.highLevel);
}

// Filter by environment
const environmentCompatibleCreatures = availableCreatures.filter(creature => 
  creature.environment.includes(environment) || creature.environment.includes('any')
);

// Build encounter
