  partyLevel,
  partySize,
  environment,
  budget: encounterBudget,
  creatures: [],
  tactics: '',
  terrainFeatures: [],
  complications: [],
  rewards: {}
};

// Select creatures based on encounter type
let remainingBudget = encounterBudget;
const selectedCreatures = [];

switch (encounterType) {
  case 'single-monster':
    // Find one strong creature
    const soloCreature = environmentCompatibleCreatures.find(c => c.cr * 2 <= remainingBudget) ||
                        environmentCompatibleCreatures.reduce((prev, curr) => 
                          curr.cr > prev.cr ? curr : prev, environmentCompatibleCreatures[0]);
    selectedCreatures.push({ ...soloCreature, count: 1, role: 'boss' });
    break;

  case 'mixed-group':
    // Mix of different creature types
    const leader = environmentCompatibleCreatures.find(c => c.cr <= remainingBudget * 0.4) ||
                   environmentCompatibleCreatures[Math.floor(environmentCompatibleCreatures.length / 2)];
    selectedCreatures.push({ ...leader, count: 1, role: 'leader' });
    remainingBudget -= leader.cr * 2;

    // Add minions
    const minionType = environmentCompatibleCreatures.find(c => c.cr <= remainingBudget * 0.3) ||
                      environmentCompatibleCreatures[0];
    const minionCount = Math.floor(remainingBudget / (minionType.cr * 2));
    if (minionCount > 0) {
      selectedCreatures.push({ ...minionType, count: minionCount, role: 'minion' });
    }
    break;

  case 'horde':
    // Many weak creatures
    const hordeType = environmentCompatibleCreatures.find(c => c.cr <= 2) ||
                     environmentCompatibleCreatures.reduce((prev, curr) => 
                       curr.cr < prev.cr ? curr : prev, environmentCompatibleCreatures[0]);
    const hordeCount = Math.floor(remainingBudget / (hordeType.cr * 2));
    selectedCreatures.push({ ...hordeType, count: hordeCount, role: 'horde' });
    break;

  default:
    // Balanced encounter
    const balancedCreatures = environmentCompatibleCreatures.slice(0, 3);
    balancedCreatures.forEach((creature, index) => {
      const maxCount = Math.floor(remainingBudget / (creature.cr * 2));
      const count = Math.min(maxCount, Math.max(1, Math.floor((4 - index) / 2)));
      if (count > 0) {
        selectedCreatures.push({ ...creature, count, role: index === 0 ? 'primary' : 'secondary' });
        remainingBudget -= creature.cr * count * 2;
      }
    });
}

encounter.creatures = selectedCreatures;

// Generate tactics
const tactics = [];
selectedCreatures.forEach(creature => {
  if (creature.role === 'boss' || creature.role === 'leader') {
    tactics.push(`${creature.name} leads the attack, focusing on spellcasters first`);
  } else if (creature.role === 'minion') {
    tactics.push(`${creature.name}s surround the party, using flanking tactics`);
  } else if (creature.role === 'skirmisher') {
    tactics.push(`${creature.name}s use hit-and-run tactics`);
  }
});
encounter.tactics = tactics.join('. ');

// Generate terrain features based on environment
const terrainFeatures = {
