    const results = creatureLibrary.filter(c => {
      if (searchCriteria.name && !c.name.toLowerCase().includes(searchCriteria.name.toLowerCase())) {
        return false;
      }
      if (searchCriteria.cr && c.cr !== searchCriteria.cr) {
        return false;
      }
