    totalAdjustedXP += adjustedXP * creature.count;
  });

  // Calculate XP thresholds
  const thresholds = {
    1: { easy: 25, medium: 50, hard: 75, deadly: 100 },
    2: { easy: 50, medium: 100, hard: 150, deadly: 200 },
    3: { easy: 75, medium: 150, hard: 225, deadly: 300 },
    4: { easy: 100, medium: 200, hard: 300, deadly: 400 },
    5: { easy: 125, medium: 250, hard: 375, deadly: 500 },
