const analyzeEncounter = (encounterCreatures, partyData) => {
  const analysis = {
    actionEconomy: { party: partyData.length, enemies: 0 },
    averageDamage: { party: 0, enemies: 0 },
    survivability: { party: 0, enemies: 0 },
    crowdControl: { party: 0, enemies: 0 },
    recommendations: []
  };

  // Calculate enemy metrics
  encounterCreatures.forEach(creature => {
    analysis.actionEconomy.enemies += creature.count;

    // Estimate average damage per round
    const avgDamage = estimateCreatureDamage(creature);
    analysis.averageDamage.enemies += avgDamage * creature.count;

    // Estimate survivability
    const survivability = creature.hp * creature.count;
    analysis.survivability.enemies += survivability;
  });

  // Calculate party metrics (simplified)
  analysis.averageDamage.party = partyData.length * 15; // Assume 15 damage per character
  analysis.survivability.party = partyData.reduce((sum, pc) => sum + pc.maxHp, 0);

  // Generate recommendations
  if (analysis.actionEconomy.enemies > analysis.actionEconomy.party * 1.5) {
    analysis.recommendations.push('Enemies outnumber the party significantly - consider reducing enemy count or increasing party resources');
  }

  if (analysis.averageDamage.enemies > analysis.averageDamage.party * 1.2) {
    analysis.recommendations.push('Enemy damage output is high - ensure party has adequate healing and defenses');
  }

  if (analysis.survivability.enemies > analysis.survivability.party * 2) {
