// Wave progression logic
const progressWave = (currentWave, encounterState) => {
  const nextWave = currentWave + 1;

  if (nextWave > multiWaveSystem.waves.length) {
    return { status: 'completed', nextWave: null };
  }

  const wave = multiWaveSystem.waves[nextWave - 1];

  // Check trigger conditions
  const triggerMet = evaluateTrigger(wave.trigger, encounterState);

  if (triggerMet) {
    return { status: 'triggered', nextWave, wave, message: `Wave ${nextWave}: ${wave.name} begins!` };
  } else {
    return { status: 'waiting', nextWave, message: `Waiting for trigger condition: ${wave.trigger.condition}` };
  }
};

// Evaluate wave trigger conditions
const evaluateTrigger = (trigger, encounterState) => {
  switch (trigger.type) {
    case 'immediate':
      return true;
    case 'condition':
      // Evaluate specific conditions
      if (trigger.condition.includes('wave defeated')) {
        const waveNumber = parseInt(trigger.condition.match(/\d+/)?.[0] || '1');
        return encounterState.wavesCompleted >= waveNumber;
      }
      if (trigger.condition.includes('rounds elapsed')) {
        const rounds = parseInt(trigger.condition.match(/\d+/)?.[0] || '3');
        return encounterState.currentRound >= rounds;
      }
      return false;
    case 'time':
      return encounterState.elapsedTime >= trigger.value;
    case 'custom':
      // Custom trigger logic would go here
      return false;
    default:
      return false;
  }
};

