  if (environmentalFactors.lighting === 'darkness') {
    // Give creatures darkvision or add creatures with night vision
    adjustments.specialEvents.push({
      type: 'environmental',
      description: 'Creatures have advantage in darkness',
      effect: 'Enemy attacks have advantage while party has disadvantage'
    });
  }

  return adjustments;
};

// Calculate wave rewards
const calculateWaveRewards = (wave, performanceMetrics, totalWaves) => {
  const baseXP = wave.creatures.reduce((total, creature) => {
    return total + (creature.cr * 100 * creature.count);
  }, 0);

  let bonusMultiplier = 1.0;

  // Performance bonuses
  if (performanceMetrics.damageTaken < performanceMetrics.maxHP * 0.3) {
    bonusMultiplier += 0.2; // 20% bonus for minimal damage
  }

  if (performanceMetrics.roundsCompleted < performanceMetrics.expectedRounds * 0.7) {
    bonusMultiplier += 0.15; // 15% bonus for speed
  }

  if (performanceMetrics.noCasualties) {
    bonusMultiplier += 0.25; // 25% bonus for no casualties
  }

  // Wave completion bonus
  const waveBonus = (wave.id / totalWaves) * 0.1; // Up to 10% extra for later waves
  bonusMultiplier += waveBonus;

  const totalXP = Math.round(baseXP * bonusMultiplier);

  return {
    base: baseXP,
    performance: Math.round(baseXP * (bonusMultiplier - 1)),
    total: totalXP,
    breakdown: {
      baseXP,
      speedBonus: performanceMetrics.roundsCompleted < performanceMetrics.expectedRounds * 0.7 ? Math.round(baseXP * 0.15) : 0,
      survivalBonus: performanceMetrics.damageTaken < performanceMetrics.maxHP * 0.3 ? Math.round(baseXP * 0.2) : 0,
      noCasualtyBonus: performanceMetrics.noCasualties ? Math.round(baseXP * 0.25) : 0,
      waveProgressBonus: Math.round(baseXP * waveBonus)
    }
  };
};

let response;

switch (action) {
  case 'initialize':
    response = { success: true, encounter: multiWaveSystem, message: 'Multi-wave encounter initialized' };
    break;
  case 'startWave':
    const waveResult = progressWave(waveConfiguration.currentWave, encounterData);
    response = { success: true, ...waveResult };
    break;
  case 'adjustWave':
    const adjustments = generateWaveAdjustments(waveConfiguration, triggerConditions.partyPerformance, triggerConditions.environment);
    response = { success: true, adjustments, message: 'Wave adjustments applied' };
    break;
  case 'completeWave':
    const rewards = calculateWaveRewards(waveConfiguration, triggerConditions.performance, encounterData.totalWaves);
    response = { success: true, rewards, message: 'Wave completed, rewards calculated' };
    break;
  case 'getProgress':
    response = { progress: multiWaveSystem.orchestration.successMetrics, currentWave: encounterData.currentWave };
    break;
  default:
    response = { error: 'Invalid action' };
}

return [{ json: response }];
